-- Add Zai Coder Plan LLM provider default
INSERT INTO llm_provider_defaults (default_id, provider_type, default_name, default_api_endpoint, default_configuration, form_schema, supports_streaming, supports_functions, supports_tools, supports_vision, request_template, response_template, documentation_url, help_text) VALUES ('zai-coding-plan-default', 'zai-coding-plan', 'Zai Coder Plan', 'https://api.zai.ai/v1', '{"default_model": "glm-5", "models": ["glm-5", "glm-4", "glm-4-flash"], "temperature": 0.7, "max_tokens": 4096, "cli_type": "opencode", "provider": "zai-coding-plan"}', '{"type": "object", "properties": {"api_key": {"type": "string", "title": "API Key", "description": "Your Zai API key"}, "default_model": {"type": "string", "title": "Default Model", "default": "glm-5", "enum": ["glm-5", "glm-4", "glm-4-flash"]}, "temperature": {"type": "number", "title": "Temperature", "default": 0.7, "minimum": 0.0, "maximum": 2.0}, "max_tokens": {"type": "integer", "title": "Max Tokens", "default": 4096, "minimum": 1, "maximum": 32768}}, "required": ["api_key"]}', true, true, true, false, '{"model": "{{model}}", "messages": [{"role": "user", "content": "{{prompt}}"}], "temperature": {{temperature}}, "max_tokens": {{max_tokens}}}', '{"text": "{{choices.0.message.content}}", "model": "{{model}}", "finish_reason": "{{choices.0.finish_reason}}"}', 'https://docs.zai.ai', 'Configure Zai Coder Plan for agent execution via OpenCode with GLM-5 and other Zai models.') ON CONFLICT (default_id) DO NOTHING;
